// === MONTA A URL DO GRÁFICO (Image-Charts / Chart.js 2.8) ===
// Este workflow NAO calcula nada. Ele recebe a especificacao pronta do agente
// (que ja tem os numeros da Consulta Financeira) e só desenha.

let chart = $json;

// --- 1. Parse robusto do que o agente mandou ---
// Aceita: string JSON, string com ```json, ou objeto direto.
const bruto = chart.dados_grafico ?? chart.grafico ?? chart.output;

if (typeof bruto === 'string') {
  try {
    const jsonMatch = bruto.match(/\{[\s\S]*\}/); // ignora texto antes/depois
    const jsonString = jsonMatch ? jsonMatch[0] : bruto;
    const jsonClean = jsonString
      .replace(/```json/g, '')
      .replace(/```/g, '')
      .replace(/\/\/.*$/gm, '')
      .replace(/\/\*[\s\S]*?\*\//g, '');
    chart = JSON.parse(jsonClean);
  } catch (e) {
    return [{ json: { url: null, erro: 'JSON invalido vindo do agente: ' + e.message, bruto: bruto } }];
  }
} else if (bruto && typeof bruto === 'object') {
  chart = bruto;
}

// --- 2. Validação ---
if (!chart || !chart.labels || !chart.values) {
  return [{ json: { url: null, erro: 'Configuracao de grafico invalida', bruto: chart } }];
}

let tipo = String(chart.tipo || 'barras').toLowerCase();
if (['linha', 'barras', 'pizza'].indexOf(tipo) === -1) tipo = 'barras'; // fallback seguro

// Pizza aceita no maximo 7 fatias — acima disso vira ilegivel
const MAX_FATIAS = 7;

// --- 3. Estilo ---
const baseUrl = 'https://image-charts.com/chart.js/2.8.0';
const background = 'white';
const width = 900;
const height = 500;
const colors = [
  'rgba(46,134,171,1)',   // azul
  'rgba(231,111,81,1)',   // coral
  'rgba(42,157,143,1)',   // verde
  'rgba(233,196,106,1)',  // amarelo
  'rgba(138,107,161,1)',  // roxo
  'rgba(244,162,97,1)',   // laranja
  'rgba(108,117,125,1)'   // cinza
];

// Evita URL gigante / eixo ilegível
const cortaLabel = (l) => {
  const s = String(l);
  return s.length > 18 ? s.slice(0, 17) + '…' : s;
};
const labels = (chart.labels || []).slice(0, 12).map(cortaLabel);

// 1234.5 -> "1.235"  |  12.34 -> "12,34"
const fmtBR = (n) => {
  const v = Number(n) || 0;
  if (Math.abs(v) >= 1000) {
    return Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  }
  return v.toFixed(2).replace('.', ',');
};

// --- 4. Datasets (série única = array | múltiplas séries = objeto) ---
const alinha = (arr) => {
  const a = Array.isArray(arr) ? arr.slice(0, labels.length) : [];
  while (a.length < labels.length) a.push(0); // completa lacunas
  return a;
};

const buildDatasets = (values) => {
  const multi = !Array.isArray(values) && typeof values === 'object' && values !== null;

  if (multi) {
    return Object.entries(values).slice(0, 6).map(([nome, dados], i) => ({
      label: nome,
      data: alinha(dados),
      fill: false,
      borderColor: colors[i % colors.length],
      backgroundColor: tipo === 'linha'
        ? colors[i % colors.length]
        : colors[i % colors.length].replace('1)', '0.85)'),
      borderWidth: tipo === 'linha' ? 3 : 1,
      tension: 0.3,
      pointRadius: 4
    }));
  }

  return [{
    label: chart.descricao || 'Valores',
    data: alinha(values),
    fill: false,
    borderColor: colors[0],
    backgroundColor: tipo === 'linha' ? colors[0] : colors[0].replace('1)', '0.85)'),
    borderWidth: tipo === 'linha' ? 3 : 1,
    tension: 0.3,
    pointRadius: 4
  }];
};

// --- 5. Config ---
let config;

if (tipo === 'pizza') {
  // Pizza aceita uma serie só. Se vier objeto, usa a primeira.
  let dados = Array.isArray(chart.values)
    ? chart.values.slice()
    : (Object.values(chart.values)[0] || []).slice();

  let fatias = labels.map((l, i) => ({ label: l, valor: Math.abs(Number(dados[i]) || 0) }))
    .filter((f) => f.valor > 0)
    .sort((a, b) => b.valor - a.valor);

  // Agrupa a cauda em "Outros" para nao virar um confete ilegivel
  if (fatias.length > MAX_FATIAS) {
    const principais = fatias.slice(0, MAX_FATIAS - 1);
    const resto = fatias.slice(MAX_FATIAS - 1).reduce((a, f) => a + f.valor, 0);
    fatias = principais.concat([{ label: 'Outros', valor: resto }]);
  }

  const total = fatias.reduce((a, f) => a + f.valor, 0);

  // Legenda rica: "Moradia: 13.100 (57,9%)"
  const richLabels = fatias.map((f) => {
    const pct = total > 0 ? ((f.valor / total) * 100).toFixed(1).replace('.', ',') : '0,0';
    return f.label + ': ' + fmtBR(f.valor) + ' (' + pct + '%)';
  });

  config = {
    type: 'pie',
    data: {
      labels: richLabels,
      datasets: [{
        data: fatias.map((f) => f.valor),
        backgroundColor: fatias.map((f, i) => colors[i % colors.length]),
        borderColor: 'white',
        borderWidth: 2
      }]
    },
    options: {
      responsive: true,
      title: { display: true, text: chart.titulo || 'Composição', fontSize: 16 },
      legend: {
        position: 'right',
        labels: { boxWidth: 12, fontSize: 11, padding: 12 }
      },
      plugins: {
        datalabels: {
          display: true,
          color: 'white',
          font: { weight: 'bold', size: 13 },
          anchor: 'center',
          align: 'center'
        }
      }
    }
  };
} else {
  const datasets = buildDatasets(chart.values);

  config = {
    type: tipo === 'linha' ? 'line' : 'bar',
    data: { labels, datasets },
    options: {
      responsive: true,
      title: { display: true, text: chart.titulo || 'Transações', fontSize: 16 },
      legend: { position: 'top', display: datasets.length > 1 },
      scales: {
        yAxes: [{
          ticks: { beginAtZero: true },
          scaleLabel: { display: !!chart.descricao, labelString: (chart.descricao || '').slice(0, 35) }
        }],
        xAxes: [{ ticks: { autoSkip: false } }]
      }
    }
  };
}

// --- 6. URL ---
const jsonConfig = encodeURIComponent(JSON.stringify(config));
const url = baseUrl + '?bkg=' + background + '&width=' + width + '&height=' + height + '&c=' + jsonConfig;

return [{
  json: {
    url,
    url_muito_longa: url.length > 8000, // Image-Charts pode recusar URLs enormes
    tipo,
    chart
  }
}];
